import{_ as l,o as i,c as e,O as o}from"./chunks/framework.db831a78.js";const b=JSON.parse('{"title":"MySQL","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/05-MySQL.md","filePath":"interview/后端/Java/05-MySQL.md","lastUpdated":null}'),n={name:"interview/后端/Java/05-MySQL.md"};function r(t,a,d,h,u,c){return i(),e("div",null,a[0]||(a[0]=[o('<h1 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="innodb-索引-b-树结构-聚簇-非聚簇索引-★★★" tabindex="-1">InnoDB 索引 B+ 树结构；聚簇/非聚簇索引 ★★★ <a class="header-anchor" href="#innodb-索引-b-树结构-聚簇-非聚簇索引-★★★" aria-label="Permalink to &quot;InnoDB 索引 B+ 树结构；聚簇/非聚簇索引 ★★★&quot;">​</a></h2><ul><li>B+ 树：非叶子节点只存键（索引），叶子节点存数据且用链表连接，支持范围查询与顺序扫描；矮胖结构减少磁盘 IO。</li><li>聚簇索引：叶子存整行数据，InnoDB 主键即聚簇索引；非聚簇索引（二级索引）叶子存主键，需回表查行。</li><li>无主键时 InnoDB 会选唯一非空索引或隐式 rowid 作聚簇索引。</li></ul><h2 id="联合索引最左前缀原则-索引失效场景-★★★" tabindex="-1">联合索引最左前缀原则；索引失效场景 ★★★ <a class="header-anchor" href="#联合索引最左前缀原则-索引失效场景-★★★" aria-label="Permalink to &quot;联合索引最左前缀原则；索引失效场景 ★★★&quot;">​</a></h2><ul><li>联合索引按 (a,b,c) 顺序，只有走 a 前缀才生效，如 (a)、(a,b)、(a,b,c)；跳过中间列会中断（(a,c) 只用 a）。</li><li>失效：对索引列用函数/运算、隐式类型转换、模糊 <code>%like</code> 前缀、范围列后的列失效、or 的两边不都走索引、is not null 等。</li></ul><h2 id="事务-acid-四种隔离级别-mvcc-★★★" tabindex="-1">事务 ACID；四种隔离级别；MVCC ★★★ <a class="header-anchor" href="#事务-acid-四种隔离级别-mvcc-★★★" aria-label="Permalink to &quot;事务 ACID；四种隔离级别；MVCC ★★★&quot;">​</a></h2><ul><li>ACID：原子性（undo log 回滚）、一致性、隔离性（锁 + MVCC）、持久性（redo log）。</li><li>隔离级别：读未提交、读已提交、可重复读（默认，解决不可重复读）、串行化（解决幻读）。对应问题：脏读、不可重复读、幻读。</li><li>MVCC：通过隐藏列（trx_id、roll_pointer）+ undo log 版本链 + ReadView 判断可见性，实现无锁读；RR 下快照读解决幻读，当前读（for update）需靠间隙锁。</li></ul><h2 id="redo-log、undo-log、binlog-作用-★★★" tabindex="-1">redo log、undo log、binlog 作用 ★★★ <a class="header-anchor" href="#redo-log、undo-log、binlog-作用-★★★" aria-label="Permalink to &quot;redo log、undo log、binlog 作用 ★★★&quot;">​</a></h2><ul><li>redo log：InnoDB 重做日志，物理日志，崩溃恢复，保证持久性（WAL 先写日志）。</li><li>undo log：逻辑日志，记录反操作，用于回滚与 MVCC。</li><li>binlog：Server 层逻辑日志，用于主从复制与数据恢复，记录所有变更。</li></ul><h2 id="innodb-锁机制-行锁、表锁、意向锁、间隙锁-幻读-★★★" tabindex="-1">InnoDB 锁机制：行锁、表锁、意向锁、间隙锁；幻读 ★★★ <a class="header-anchor" href="#innodb-锁机制-行锁、表锁、意向锁、间隙锁-幻读-★★★" aria-label="Permalink to &quot;InnoDB 锁机制：行锁、表锁、意向锁、间隙锁；幻读 ★★★&quot;">​</a></h2><ul><li>行锁（记录锁）、间隙锁（锁区间，防插入）、临键锁（记录+间隙，RR 下默认，解决幻读）。</li><li>表锁与意向锁（IS/IX，表级，表示后续要对行加锁，协调行锁与表锁）。</li><li>索引不命中时行锁升级为表锁。</li></ul><h2 id="explain-字段含义-慢查询优化-★★★" tabindex="-1">explain 字段含义；慢查询优化 ★★★ <a class="header-anchor" href="#explain-字段含义-慢查询优化-★★★" aria-label="Permalink to &quot;explain 字段含义；慢查询优化 ★★★&quot;">​</a></h2><ul><li>字段：id（执行顺序）、select_type、type（访问类型，const&gt;eq_ref&gt;ref&gt;range&gt;index&gt;all）、possible_keys/key（实际用索引）、rows（扫描行数估算）、Extra（Using index 覆盖、Using filesort 排序、Using temporary 临时表）。</li><li>优化：加合适索引、覆盖索引避免回表、避免 filesort/temporary、改写深分页、避免索引失效。</li></ul><h2 id="主从复制原理-读写分离-分库分表-★★★" tabindex="-1">主从复制原理；读写分离；分库分表 ★★★ <a class="header-anchor" href="#主从复制原理-读写分离-分库分表-★★★" aria-label="Permalink to &quot;主从复制原理；读写分离；分库分表 ★★★&quot;">​</a></h2><ul><li>主从：主库写 binlog → 从库 IO 线程拉取写 relay log → SQL 线程重放；异步为主，半同步减少延迟。</li><li>读写分离：写主读从，中间件（ShardingSphere/MyCat）或客户端路由；注意复制延迟导致读旧数据。</li><li>分库分表：垂直（按业务/字段拆）、水平（按主键哈希/范围分片）；中间件 ShardingSphere；引入分布式 ID、跨库 join 与事务问题。</li></ul><h2 id="索引下推-icp、覆盖索引-★★☆" tabindex="-1">索引下推 ICP、覆盖索引 ★★☆ <a class="header-anchor" href="#索引下推-icp、覆盖索引-★★☆" aria-label="Permalink to &quot;索引下推 ICP、覆盖索引 ★★☆&quot;">​</a></h2><ul><li>覆盖索引：查询列都在索引中（Extra=Using index），避免回表；索引下推 ICP：存储引擎层先按索引列过滤再回表，减少回表次数。</li></ul><h2 id="为什么用-b-树不用-b-树-哈希-跳表-★★☆" tabindex="-1">为什么用 B+ 树不用 B 树/哈希/跳表 ★★☆ <a class="header-anchor" href="#为什么用-b-树不用-b-树-哈希-跳表-★★☆" aria-label="Permalink to &quot;为什么用 B+ 树不用 B 树/哈希/跳表 ★★☆&quot;">​</a></h2><ul><li>B 树非叶子也存数据，单页存键少、树更高、范围查询要回跳；B+ 树数据全在叶子且链表串联，更适合磁盘 IO 与范围查询。</li><li>哈希不支持范围/排序、碰撞退化；跳表内存结构不适合磁盘页。</li></ul><h2 id="count-优化、深分页-★★★" tabindex="-1">count(*) 优化、深分页 ★★★ <a class="header-anchor" href="#count-优化、深分页-★★★" aria-label="Permalink to &quot;count(*) 优化、深分页 ★★★&quot;">​</a></h2><ul><li>count(*)：优先用最小二级索引扫描（覆盖）；近似值可用 explain 或 information_schema（InnoDB 不维护精确值）。</li><li>深分页 <code>limit 100000,10</code> 慢：改「延迟关联」（先查主键再回表）、记上次主键 id 游标翻页（<code>where id &gt; ?</code>）。</li></ul><h2 id="三大范式、innodb-vs-myisam-★★☆" tabindex="-1">三大范式、InnoDB vs MyISAM ★★☆ <a class="header-anchor" href="#三大范式、innodb-vs-myisam-★★☆" aria-label="Permalink to &quot;三大范式、InnoDB vs MyISAM ★★☆&quot;">​</a></h2><ul><li>1NF 列不可分、2NF 消除部分依赖、3NF 消除传递依赖；实际常适当反范式（冗余）换性能。</li><li>InnoDB 支持事务/行锁/外键/MVCC，崩溃恢复强，聚簇索引；MyISAM 不支持事务、表级锁、非聚簇，读快但已边缘化。</li></ul><h2 id="隐式类型转换导致索引失效-★★☆" tabindex="-1">隐式类型转换导致索引失效 ★★☆ <a class="header-anchor" href="#隐式类型转换导致索引失效-★★☆" aria-label="Permalink to &quot;隐式类型转换导致索引失效 ★★☆&quot;">​</a></h2><ul><li>如 <code>where phone = 138...</code>（字符串列对比数字），MySQL 会把列转为数字，导致隐式转换、索引失效；应保持类型一致或显式转换。</li></ul>',26)]))}const m=l(n,[["render",r]]);export{b as __pageData,m as default};
